package org.apache.commons.lang3;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_14_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        CharSequence cs1 = new StringBuilder("test");
        CharSequence cs2 = new StringBuffer("test");
        // The expected behavior is that these two CharSequences are considered equal
        assertTrue(StringUtils.equals(cs1, cs2));
    }
}

